public class BallItem extends GameItem {
    BallThread twin;                      // package-private: pair-internal
    private boolean suspended;
    @Override public void draw() { ... }
    public void move()           { ... }
    @Override public void click() { suspended = !suspended; twin.toggle(suspended); }
    static BallItem newBall(int x, int y) {            // factory creates the pair
        BallItem item = new BallItem(); BallThread thread = new BallThread();
        item.twin = thread; thread.twin = item;        // link before publishing
        thread.start(); return item;
    }
}

