public interface Suspendable {                     // second protocol, behaviour only
    boolean suspended();
    default void toggle() { ... }
}
public class BallItem extends GameItem implements Suspendable {
    private final BallThread twin;                 // platform end stays a class
    @Override public void click() { toggle(); twin.applySuspended(suspended()); }
}
